import { copyFile, mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const repositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const webRoot = resolve(repositoryRoot, "apps/web");
const outputDirectory = resolve(webRoot, "dist/licenses");
const lock = JSON.parse(await readFile(resolve(repositoryRoot, "package-lock.json"), "utf8"));
const webPackage = JSON.parse(await readFile(resolve(webRoot, "package.json"), "utf8"));
const packageEntries = lock.packages ?? {};

const pending = Object.keys(webPackage.dependencies ?? {}).map((name) => ({
  name,
  parentPath: ""
}));
const selected = new Map();

while (pending.length > 0) {
  const dependency = pending.shift();
  const packagePath = resolvePackagePath(dependency.name, dependency.parentPath);
  if (!packagePath || selected.has(packagePath)) {
    continue;
  }

  const metadata = packageEntries[packagePath];
  if (!metadata || metadata.link === true) {
    throw new Error(`Cannot resolve distributable dependency ${dependency.name}`);
  }

  selected.set(packagePath, metadata);
  for (const name of Object.keys(metadata.dependencies ?? {})) {
    pending.push({ name, parentPath: packagePath });
  }
  for (const name of Object.keys(metadata.optionalDependencies ?? {})) {
    if (resolvePackagePath(name, packagePath)) {
      pending.push({ name, parentPath: packagePath });
    }
  }
  for (const name of Object.keys(metadata.peerDependencies ?? {})) {
    if (resolvePackagePath(name, packagePath)) {
      pending.push({ name, parentPath: packagePath });
    }
  }
}

const sections = [];
for (const [packagePath, metadata] of [...selected.entries()].sort(([left], [right]) =>
  left.localeCompare(right)
)) {
  const packageName = packageNameFromPath(packagePath);
  const packageDirectory = resolve(repositoryRoot, packagePath);
  const license = await readLicense(packageDirectory);
  sections.push(
    [
      "=".repeat(80),
      `${packageName}@${metadata.version ?? "unknown"}`,
      `SPDX license: ${metadata.license ?? "unknown"}`,
      "=".repeat(80),
      "",
      license.trim(),
      ""
    ].join("\n")
  );
}

await mkdir(outputDirectory, { recursive: true });
await copyFile(resolve(repositoryRoot, "LICENSE"), resolve(outputDirectory, "LICENSE"));
await copyFile(resolve(repositoryRoot, "NOTICE"), resolve(outputDirectory, "NOTICE"));
await writeFile(
  resolve(outputDirectory, "THIRD_PARTY_LICENSES.txt"),
  [
    "Third-party licenses for the TestHistory web distribution",
    "Generated from package-lock.json; do not edit this file manually.",
    "",
    ...sections
  ].join("\n"),
  "utf8"
);

console.log(`Web license bundle generated for ${selected.size} packages`);

function resolvePackagePath(name, parentPath) {
  const candidates = [];
  if (parentPath) {
    candidates.push(`${parentPath}/node_modules/${name}`);
  }
  candidates.push(`node_modules/${name}`);
  return candidates.find((candidate) => packageEntries[candidate]) ?? null;
}

function packageNameFromPath(packagePath) {
  const marker = "node_modules/";
  const lastMarker = packagePath.lastIndexOf(marker);
  return packagePath.slice(lastMarker + marker.length);
}

async function readLicense(packageDirectory) {
  for (const fileName of [
    "LICENSE",
    "LICENSE.md",
    "LICENSE.txt",
    "LICENCE",
    "LICENCE.md",
    "LICENCE.txt",
    "COPYING"
  ]) {
    try {
      return await readFile(resolve(packageDirectory, fileName), "utf8");
    } catch (error) {
      if (error?.code !== "ENOENT") {
        throw error;
      }
    }
  }
  throw new Error(`No license file found in ${packageDirectory}`);
}
